import pytest

from sales_dashboard.loader import daily_conversion_counts, dedupe_sessions, parse_session_log
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_conversion_rate_counts_none_as_unconverted():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5
    assert conversion_rate([]) == 0.0


def test_pooled_rate_weights_sessions():
    groups = {"a": [{"converted": True}], "b": [{"converted": None}] * 3, "c": []}
    assert pooled_conversion_rate(groups) == 0.25
    assert pooled_conversion_rate({"a": []}) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (2, 7), (5, 9)])
def test_trailing_window(days, expected):
    assert conversions_in_window([2, 3, 4], days) == expected


def test_parse_flags_whitespace_and_skipped_lines():
    lines = ["", " \t", "  # header", " a , 1 , 1 ", " b , 2 , 0 ", " c , 3 , "]
    assert parse_session_log(lines) == [
        {"id": "a", "day": 1, "converted": True},
        {"id": "b", "day": 2, "converted": False},
        {"id": "c", "day": 3, "converted": None},
    ]


@pytest.mark.parametrize("bad", ["x,1", "x,1,0,1", "x,not-an-int,0"])
def test_parse_errors_count_skipped_lines(bad):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_session_log(["  # header", "x,1,1", "", bad])


def test_dedupe_keeps_last_input_record_not_latest_day():
    old = {"id": "a", "day": 4, "converted": True}
    new = {"id": "a", "day": 2, "converted": False}
    b = {"id": "b", "day": 2, "converted": True}
    z = {"id": "z", "day": 1, "converted": True}
    assert dedupe_sessions([old, b, z, new]) == [z, new, b]


def test_daily_counts_include_only_requested_days():
    events = [{"day": day, "converted": True} for day in [0, 1, 1, 3, 4]]
    events.append({"day": 2, "converted": False})
    assert daily_conversion_counts(events, 1, 3) == [2, 0, 1]
    assert daily_conversion_counts(events, 3, 1) == []


def test_summary_uses_calendar_days_and_nonempty_groups():
    groups = {"a": [{"day": 1, "converted": True}], "b": [
        {"day": 2, "converted": True}, {"day": 5, "converted": None}
    ], "empty": []}
    assert campaign_summary(groups, 3) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert campaign_summary({}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_rates_and_rankings():
    groups = {"z": [{"converted": True}], "empty": [], "b": [{"converted": None}],
              "a": [{"converted": True}]}
    assert list(conversion_rate_by_group(groups).items()) == [
        ("a", 1.0), ("b", 0.0), ("empty", None), ("z", 1.0)
    ]
    assert top_converting_groups(groups, 1) == ["a"]
    assert top_converting_groups(groups, 5) == ["a", "z", "b"]


@pytest.mark.parametrize("counts, expected", [([], 0), ([-1, 0], 0), ([1, 0, 2, 3, -1, 4], 2)])
def test_streak_requires_consecutive_positive_counts(counts, expected):
    assert longest_conversion_streak(counts) == expected
